import{_ as t,a as o,b as s}from"./chunks/yolo_fine-tuning.DTT1tLAE.js";import{_ as r,o as a,c as n,a0 as i}from"./chunks/framework.Ckbw5VQO.js";const f=JSON.parse('{"title":"YOLO","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models/yolo.md","filePath":"guide/models/yolo.md"}'),l={name:"guide/models/yolo.md"};function d(h,e,c,g,m,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="yolo" tabindex="-1">YOLO <a class="header-anchor" href="#yolo" aria-label="Permalink to &quot;YOLO&quot;">​</a></h1><p>In geo-ml, rather than training a model from scratch (which would require millions of images), we start from a <strong>YOLOv8 model already trained</strong> on a large general-purpose dataset - it already knows how to recognise shapes, edges, and textures. We then <strong>specialise it for our task</strong> (<em>fine-tuning</em>): we continue its training on our two classes, <strong>pools</strong> &amp; <strong>buildings</strong>, using a small set of IGN images. The model reuses what it already knows and just learns to recognise our specific objects.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong><a href="https://arxiv.org/abs/2208.00773" target="_blank" rel="noreferrer">YOLO</a></strong> (<em>You Only Look Once</em>) is a family of <strong>object-detection</strong> models: given an image, they return a list of <strong>bounding boxes</strong>, each with a <strong>class</strong> and a <strong>confidence score</strong>. It&#39;s the model at the heart of this project.</p></div><h2 id="how-it-works" tabindex="-1"><a href="https://blent.ai/blog/a/detection-images-yolo-tensorflow" target="_blank" rel="noreferrer">How it works</a> <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;[How it works](https://blent.ai/blog/a/detection-images-yolo-tensorflow)&quot;">​</a></h2><img src="'+t+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><h3 id="🔹-before-yolo-two-stages-two-networks-e-g-faster-r-cnn" tabindex="-1">🔹 Before YOLO: two stages, two networks (e.g. <a href="https://arxiv.org/abs/1506.01497" target="_blank" rel="noreferrer">Faster R-CNN</a>) <a class="header-anchor" href="#🔹-before-yolo-two-stages-two-networks-e-g-faster-r-cnn" aria-label="Permalink to &quot;🔹 Before YOLO: two stages, two networks (e.g. [Faster R-CNN](https://arxiv.org/abs/1506.01497))&quot;">​</a></h3><p>The detector passes the image through the network <strong>multiple times</strong>:</p><ol><li><strong>Propose</strong> hundreds of regions that might contain an object.</li><li><strong>Classify</strong> each region <em>one by one</em> by re-running it through a CNN.</li></ol><p>=&gt; Many repeated computations: <strong>accurate, but slow</strong>.</p><h3 id="🔹-yolo-does-everything-in-a-single-pass" tabindex="-1">🔹 <a href="https://medium.com/@fatimazahra.belharar/object-detection-using-cnn-an-introduction-to-the-yolo-algorithm-df0f7b173c6" target="_blank" rel="noreferrer">YOLO does everything in <strong>a single pass</strong></a> <a class="header-anchor" href="#🔹-yolo-does-everything-in-a-single-pass" aria-label="Permalink to &quot;🔹 [YOLO does everything in **a single pass**](https://medium.com/@fatimazahra.belharar/object-detection-using-cnn-an-introduction-to-the-yolo-algorithm-df0f7b173c6)&quot;">​</a></h3><p>The image traverses the network <strong>once</strong> and everything is predicted at once:</p><ol><li>The image is resized (here <strong>640×640</strong>) and passed <strong>once</strong> through the CNN.</li><li>The network splits the image into a grid and predicts directly, for each cell, candidate boxes: position <code>(cx, cy)</code>, size <code>(w, h)</code>, objectness score and class - <strong>all simultaneously</strong>.</li><li>A simple final cleanup (<strong>NMS</strong>) removes duplicates. It&#39;s not a network, just a filter.</li></ol><p>=&gt; A single network pass: <strong>fast</strong> (ideal for real-time &amp; the browser), at the cost of slightly lower precision on very small or very dense objects.</p><h2 id="nms-non-maximum-suppression" tabindex="-1"><a href="https://learnopencv.com/non-maximum-suppression-theory-and-implementation-in-pytorch/" target="_blank" rel="noreferrer">NMS (Non-Maximum Suppression)</a> <a class="header-anchor" href="#nms-non-maximum-suppression" aria-label="Permalink to &quot;[NMS (Non-Maximum Suppression)](https://learnopencv.com/non-maximum-suppression-theory-and-implementation-in-pytorch/)&quot;">​</a></h2><p>The same object often triggers <strong>several overlapping boxes</strong>. <strong>Non-Maximum Suppression</strong> (NMS) keeps only the best one:</p><ol><li><strong>Sort</strong> boxes by confidence score, highest first.</li><li><strong>Keep</strong> the top box, then <strong>discard</strong> every box that overlaps it too much - i.e. whose <strong>IoU</strong> (<em>Intersection over Union</em>, the shared area divided by the total area) exceeds a set threshold.</li><li><strong>Repeat</strong> on the remaining boxes until none are left to process.</li></ol><p>=&gt; Result: <strong>one box per object</strong>, the one the model is most confident about.</p><img src="'+o+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><div class="info custom-block"><p class="custom-block-title">In this project, NMS runs in JavaScript</p><p>We export the ONNX model <strong>without embedded NMS</strong>, because that operation runs poorly in ONNX Runtime Web. The browser handles NMS itself (<code>frontend/src/inference/postprocess.js</code>).</p><p>=&gt; It&#39;s more reliable.</p></div><h2 id="yolov8n" tabindex="-1"><a href="https://docs.ultralytics.com/models/yolov8#overview" target="_blank" rel="noreferrer">YOLOv8n</a> <a class="header-anchor" href="#yolov8n" aria-label="Permalink to &quot;[YOLOv8n](https://docs.ultralytics.com/models/yolov8#overview)&quot;">​</a></h2><h3 id="choosing-the-nano-variant" tabindex="-1">Choosing the nano variant <a class="header-anchor" href="#choosing-the-nano-variant" aria-label="Permalink to &quot;Choosing the nano variant&quot;">​</a></h3><p>The YOLOv8 family offers five sizes. The choice depends on the deployment context - here, the model must <strong>run in the browser via ONNX Runtime Web</strong>, which puts a hard constraint on the <code>.onnx</code> file size.</p><table tabindex="0"><thead><tr><th>Variant</th><th>Parameters</th><th>ONNX size</th><th>Use</th></tr></thead><tbody><tr><td><strong>YOLOv8n</strong></td><td>~3 M</td><td>~6 MB</td><td>browser, mobile ✅</td></tr><tr><td>YOLOv8s</td><td>~11 M</td><td>~22 MB</td><td>good trade-off, acceptable load time</td></tr><tr><td>YOLOv8m</td><td>~25 M</td><td>~50 MB</td><td>GPU server</td></tr><tr><td>YOLOv8l / x</td><td>43–68 M</td><td>&gt;80 MB</td><td>max accuracy, GPU required</td></tr></tbody></table><p><code>yolov8n</code> is the project default. <code>yolov8s</code> is still usable in the browser if a longer load time is acceptable.</p><h3 id="fine-tuning-on-pools-buildings" tabindex="-1">Fine-tuning on pools &amp; buildings <a class="header-anchor" href="#fine-tuning-on-pools-buildings" aria-label="Permalink to &quot;Fine-tuning on pools &amp; buildings&quot;">​</a></h3><p>Training a detector from scratch would require millions of images and weeks of GPU compute. <strong>Fine-tuning</strong> avoids that cost: instead of relearning everything, we start from a YOLOv8 model already trained on <strong><a href="https://cocodataset.org/" target="_blank" rel="noreferrer">COCO</a></strong> (80 everyday object classes - cars, people, animals…) and specialise it on our two classes.</p><img src="'+s+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><p>The key idea: a detector is made up of two parts.</p><ul><li>The <strong>backbone</strong> has already learned to extract generic visual features - edges, textures, shapes. These skills are <em>universal</em>, valid for any object, so we <strong>keep them as-is</strong> (we say those layers are &quot;frozen&quot;).</li><li>The <strong>detection head</strong> is the part that decides <em>which object</em> and <em>where</em>. This is what we <strong>retrain</strong> on our annotated IGN images (pools / buildings).</li></ul><div class="tip custom-block"><p class="custom-block-title">Result</p><p>The model reuses all its visual knowledge and only learns what is specific to our task, in a few dozen <strong>epochs</strong> (passes over the dataset) instead of thousands. The fine-tuned weights are then exported to <code>.onnx</code> to run in the browser.</p></div>',30)])])}const y=r(l,[["render",d]]);export{f as __pageData,y as default};
